INSERT INTO scheduled_tasks VALUES('task-092a6d85f2',1,1788774300.0,'{"title": "Grant + funding digest", "instructions": "Find funding I could apply for, based on my resume.\n\nYour resume is staged in your own workspace as resume.txt (plain text, already extracted from the PDF) \u2014 read it with your file tools, by that plain filename, and use it to establish background, seniority, technical domain and eligibility.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/Documents/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and nothing gets written. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until the output file exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A file that records \"search returned nothing useful for X\" is a success; no file at all is a failure.\n\nWHAT TO SEARCH FOR \u2014 money to pursue my own work, tagged by track:\n\n[RESEARCH] and [FELLOWSHIP] \u2014 NSF, DOE, NIH, DARPA, Grants.gov listings, independent-researcher fellowships, AI safety and compute-access grant programs.\n\n[SBIR] and [STARTUP] \u2014 SBIR/STTR solicitations across agencies, state innovation and technology funds, non-dilutive startup funding, accelerators with a grant component.\n\nA [FELLOWSHIP] here means funding for my own project with no employer. Salaried fellowships and residencies where I would work for an organisation belong to the daily job automation, not this digest \u2014 skip them.\n\nFor each opportunity: name, funder, award size, deadline, eligibility requirements, link, and one honest sentence on whether I actually qualify. Be direct when eligibility is a stretch \u2014 many programs require an academic institution, a registered company, PI status, or prior awards, and saying so is more useful than an optimistic listing.\n\nSort by deadline proximity, soonest first. Drop anything already closed. Flag anything due within 14 days as urgent at the top.\n\nSave as grants-YYYY-week-WW.md.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n", "schedule": {"kind": "cron", "cron": "45 5 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-092a6d85f2", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-092a6d85f2", "task_session_id": "__task__task-092a6d85f2", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900127.0268352, "updated_at": 1788361551.519103, "next_run": 1788774300.0, "last_run": 1788169527.2666605, "last_status": "ok", "run_count": 5, "max_runs": null, "seen_runs_at": 1788270666.9345317}');
INSERT INTO scheduled_tasks VALUES('task-78fcb8b740',1,1788947100.0,'{"title": "Outside view \u2014 argue against the current approach", "instructions": "Attack the way I am currently solving my main problem. Everything else on my schedule\ntells me more about what I am already doing; this job exists to tell me what I am not considering.\nIt runs mid-week, while there is still time to change course.\n\nPICK THE TARGET:\n  1. read_file FOCUS.md in your workspace.\n  2. Take the FIRST entry under \"## Active\" and the open question attached to it. One target per\n     run \u2014 a shallow pass over five projects is worth nothing.\n  3. Name the target and its current approach in one sentence at the top of your report, so it is\n     obvious what you are arguing against.\n\nFOUR ANGLES \u2014 search each separately, do not merge them:\n  1. ALTERNATIVE APPROACHES. How else is this problem solved? Find at least two approaches that\n     are not the one I am using, and say what each buys and costs.\n  2. PRIOR ART. Who has already solved this, and how? A library, a paper, a product, a blog post\n     from someone who hit the same wall. If it exists, using it beats rebuilding it.\n  3. THE CASE AGAINST. Find real arguments against my current approach \u2014 post-mortems, \"why we\n     moved off X\" write-ups, known failure modes. Search for the criticism explicitly; a search\n     that only returns enthusiasm was the wrong search.\n  4. THE ADJACENT FIELD. One field that is not mine and has met this problem shape before. Say\n     what transfers.\n\nCLOSE WITH TWO THINGS, both required:\n  - ONE THING TO CONSIDER ABANDONING. Name the piece of the current approach with the worst\n    effort-to-payoff ratio, and say what would replace it. If you genuinely cannot find one, say\n    \"nothing \u2014 here is why the current approach holds\" and give the reason. Never leave it blank.\n  - ONE CHEAP EXPERIMENT that would show the current approach is wrong, runnable in under an hour.\n\nBUDGET: at most 8 searches and 10 page fetches. Read the pages you cite \u2014 a snippet is a pointer,\nnot evidence.\n\nRULES:\n  - Be specific and be willing to be wrong. A hedged report that offends nobody is useless here.\n  - Argue from sources you opened, not from general impressions. Attribute every claim to its URL.\n  - Do not soften the conclusion because it is inconvenient. If the honest read is \"you are\n    building the wrong thing\", write that.\n\nWrite outside-view-<YYYY-MM-DD>.md in your workspace.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.", "schedule": {"kind": "cron", "cron": "45 5 * * 3", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-78fcb8b740", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-78fcb8b740", "task_session_id": "__task__task-78fcb8b740", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.91519, "updated_at": 1788361551.519311, "next_run": 1788947100.0, "last_run": 1788342308.9040196, "last_status": "ok", "run_count": 2, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-e6e7dcad9a',0,NULL,'{"title": "Pre-open market brief \u2014 Sigma system", "instructions": "Brief me on my Sigma trading system before the market opens.\n\nHOW TO READ THE DATA \u2014 read this before starting:\nThree small files are staged in your own workspace a few minutes before each run. Read them with your file tools, by plain filename:\n- status_report.json \u2014 live account state.\n- decisions-summary.json \u2014 which decisions file was staged, the trading day, row counts by decision, and the list of GO tickers.\n- decisions-go.csv \u2014 one row per GO decision, with scores and reasons.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/quantumGlobalGroup/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and the brief never gets written. Everything you need is already staged here. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until market-brief-YYYY-MM-DD.md exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A brief that says \"news lookup failed for X\" is a success; no file at all is a failure.\n\nWHAT TO PRODUCE:\n\nstatus_report.json holds three accounts \u2014 A = Mean-Reversion, B = Momentum, C = Options/High-Vol \u2014 each with equity, cash, position count and unrealized P&L, plus portfolio_value, daily_pnl, circuit_breaker_tripped, and a `swallowed` map of suppressed API errors.\n\n1. Account state \u2014 equity and daily P&L per account, portfolio total, and what changed since the previous brief if an earlier market-brief file exists in this workspace.\n2. Active names \u2014 take go_tickers from decisions-summary.json. For each, search news since the last close and flag anything that would invalidate the thesis: earnings, guidance changes, sector shocks, M&A, regulatory action. Use decisions-go.csv for the scores and stated reason behind each. If there are more than 10 GO tickers, cover the 10 with the highest total_score and say how many you skipped.\n3. Operational health \u2014 if decisions-summary.json''s trading_day is not the current or previous trading day, say so prominently: it means the trading daemon stopped producing decision logs. Also flag circuit_breaker_tripped being true, any large counts in `swallowed`, and any account present in status_report.json but missing from accounts_seen (that account evaluated nothing). These are system failures and matter more than market commentary.\n\nLead the file with anything needing a decision before the open. This is informational \u2014 do not place, modify, or recommend specific trades to execute.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n", "schedule": {"kind": "cron", "cron": "30 7 * * 1-5", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-e6e7dcad9a", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-e6e7dcad9a", "task_session_id": "__task__task-e6e7dcad9a", "model": "openai:ornith-nothink", "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": false, "created_at": 1786900127.0080872, "updated_at": 1788361551.519733, "next_run": null, "last_run": 1786905365.4827797, "last_status": "ok", "run_count": 3, "max_runs": null, "seen_runs_at": 1787250195.8118854}');
INSERT INTO scheduled_tasks VALUES('task-4f5c834615',1,1788777000.0,'{"title": "Weekly review \u2014 what moved, what is stuck", "instructions": "Write the week''s review: what moved, what is still open, and what I keep being told\nand keep ignoring. This is the level where the daily briefs become a decision.\n\nREAD, in this order:\n  1. /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md \u2014 this week''s focus, written a few hours ago.\n  2. The week''s automation output:\n     `find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -mtime -7 | head -40`\n     (both scratch bases: ~/OpenWorker and ~/openworker-tasks)\n     Read the ones whose names say they are briefs; skip FOCUS.md copies.\n  3. The previous weekly review in /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/ \u2014 you are continuing a record.\n  4. The KB, for anything the files above do not cover: mcp__qdrant__qdrant-qdrant-find on each Active\n     project named in FOCUS.md. At most 5 queries.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/<YYYY>-W<ww>.md with these four sections, in this order:\n\n  ## Moved\n  What actually changed this week, per Active project \u2014 commits landed, questions answered,\n  things that broke and got fixed. Each line names its evidence.\n\n  ## Still open\n  Questions from FOCUS.md that are still questions. For each, say what would close it.\n\n  ## Unexamined\n  THIS IS THE POINT OF THE JOB. Anything that has been reported three or more times across the\n  daily outputs and has never changed state: the same broken dependency, the same drifted spec,\n  the same paper topic recurring, the same job or grant deadline approaching untouched.\n  Find them by grepping the accumulated outputs, not from memory:\n    `grep -rhoi ''<candidate phrase>'' --include=''*.md'' /home/iconbaypark2900/OpenWorker /home/iconbaypark2900/openworker-tasks | wc -l`\n  For each: how many times it has appeared, when it first appeared, and the smallest action that\n  would end it. Say plainly if this section is empty \u2014 do not manufacture entries.\n\n  ## Decisions waiting on me\n  At most three. Each one a question I can answer yes or no, with the consequence of each answer.\n\nBUDGET: at most 30 tool calls. Reading 12 files well beats skimming 40.\n\nRULES:\n  - Every claim traces to a file you read this run. No summarising from memory of last week.\n  - \"Nothing moved on X\" is a finding worth writing, not a gap to paper over.\n  - Do not restate the daily briefs. If a line would be equally true in yesterday''s brief, cut it.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n\nINPUT CONTRACT \u2014 count what you had before you summarise it:\n  1. This job is one level of a rollup: it reads the week''s automation output and nothing below that. Before\n     writing anything, LIST the input files and COUNT them.\n  2. Put the count in the first line of the report: \"Built from N of 5-7 days of task output expected inputs.\"\n     Name the ones that are missing.\n  3. If fewer than half are present, still write the report, but put PARTIAL in its title and\n     say in one line which period has no coverage.\n  4. Never present a partial rollup as a complete one. Every level above this one reads only\n     this file and cannot see what you were missing \u2014 an unmarked gap here becomes a\n     confident falsehood in the quarterly and then in the yearly. Right now the tree is\n     young and this WILL bite: as of 2026-09-02 weekly/ holds 1 file and quarterly/ is empty.\n", "schedule": {"kind": "cron", "cron": "30 6 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-4f5c834615", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-4f5c834615", "task_session_id": "__task__task-4f5c834615", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9131181, "updated_at": 1788361586.412415, "next_run": 1788777000.0, "last_run": 1788172227.312595, "last_status": "ok", "run_count": 2, "max_runs": null, "seen_runs_at": 1787834260.0419922}');
INSERT INTO scheduled_tasks VALUES('task-db9b445c7a',1,1788766200.0,'{"title": "Focus \u2014 derive from the week''s work", "instructions": "Work out what I am ACTUALLY pursuing right now, from evidence, and write it to\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md. Every other automation reads that file and sorts its findings by it, so this\njob is the one that decides what \"on focus\" means for the week. Infer from what I did \u2014 never from\nwhat I once said I would do.\n\nMETHOD \u2014 evidence first, in this order:\n  1. Repositories. Find them: `find /home/iconbaypark2900 -maxdepth 2 -name .git -type d | head -40`.\n     For each, `git -C <repo> log --since=\"14 days ago\" --pretty=format:''%ad %s'' --date=short | head -20`.\n     A repo with no commits in 14 days is NOT in focus, however important it looks.\n     Count AUTHORSHIP, not commits: `git -C <repo> log --since=\"14 days ago\" --pretty=''%an'' | sort | uniq -c | sort -rn | head -3`.\n     A clone that tracks upstream (llama.cpp, for one) shows hundreds of commits by people who\n     are not me. That is a dependency I follow, never a project I am working on \u2014 exclude it.\n  2. Sessions \u2014 what I have actually been talking about:\n     `sqlite3 /home/iconbaypark2900/.config/coworker/coworker.db \"select date(updated_at), agent, n_msgs, title from sessions where archived=0 and session_id not like ''__task__%'' order by updated_at desc limit 25\"`\n     Message count is the signal: a 300-message session is a project, a 3-message one is a question.\n  3. The automations'' own recent output:\n     `find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -printf ''%T@ %p\\n'' | sort -rn | head -30`.\n     What keeps showing up is a live thread whether or not I have named it.\n  4. The PREVIOUS FOCUS.md, if one exists. Read it before writing the new one.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md.\n\n  ITS FIRST LINE IS A CONTRACT, not a heading. It must be exactly:\n      # FOCUS \u2014 week of <YYYY-MM-DD>\n  dated the Monday of the week you are writing for. Seventeen other automations read that\n  date to decide whether this file is still current; without it they cannot tell a fresh\n  focus from one three weeks dead, and they will sort their findings by a focus I have\n  moved on from. If you write nothing else correctly, write that line correctly.\n\n  Then exactly these sections:\n  ## Active \u2014 at most 5. One line each: the project, the repo/path, and THE OPEN QUESTION it is\n     currently stuck on or working through. Ranked by evidence, strongest first. Name the evidence\n     (\"41 commits, 2 sessions this week\") so a later job can tell how sure to be.\n  ## Open questions \u2014 the things I am trying to answer, extracted from session titles and commit\n     messages. These are what the Outside View job attacks, so phrase each as a real question.\n  ## Went quiet \u2014 anything in the previous FOCUS.md with no activity in 14 days, with the date it\n     was last touched. Do not delete these silently; a project going quiet is information.\n  ## Parked \u2014 carried forward VERBATIM from the previous FOCUS.md. This section is mine, not\n     yours: never add to it and never remove from it.\n\nDISTRIBUTE \u2014 the research-persona jobs cannot read outside their own workspace, so FOCUS.md has\nto be copied to them:\n  Task workspaces live under TWO bases \u2014 `~/OpenWorker` for the automations created before the\n  scratch_base pref changed, `~/openworker-tasks` for the ones after. Find them, never assume one:\n  `find /home/iconbaypark2900 -maxdepth 2 -type d -name ''__task__*'' -exec cp /home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md {} \\;`\n  Then verify: `find /home/iconbaypark2900 -maxdepth 3 -name FOCUS.md -path ''*__task__*'' | wc -l`\n  and report the count. If it is smaller than the number of automations, say so.\n\nBUDGET: at most 20 tool calls. Prefer one broad git/sqlite command over ten narrow ones.\n\nRULES:\n  - Evidence or nothing. If you cannot show the commits or the sessions behind a claimed focus,\n    it does not go in Active.\n  - Five entries maximum in Active. A focus file that lists everything states nothing.\n  - Do not invent open questions. Take them from what the commits and session titles actually say.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n", "schedule": {"kind": "cron", "cron": "30 3 * * 1", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-db9b445c7a", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-db9b445c7a", "task_session_id": "__task__task-db9b445c7a", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.905548, "updated_at": 1788361609.8196, "next_run": 1788766200.0, "last_run": 1788161427.1625314, "last_status": "ok", "run_count": 2, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-d6306af97d',1,1790852400.0,'{"title": "Monthly report \u2014 themes and drift", "instructions": "Summarise the month from the weekly reviews \u2014 NOT from the daily briefs. Each level of\nthis ladder reads only the level below it; that is what keeps it affordable and what makes the\nsummaries progressively more strategic instead of progressively longer.\n\nREAD: every file in /home/iconbaypark2900/OpenWorker/knowledge/reports/weekly/ from the month just ended (4-5 files), plus\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md and last month''s report in /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/<YYYY>-<MM>.md:\n\n  ## What shipped\n  Things that reached a finished state this month. Be strict \u2014 \"worked on\" is not \"shipped\".\n\n  ## Themes\n  What the weeks had in common that no single week showed. A problem that recurred in three\n  different projects is a theme; something that happened once is not.\n\n  ## Drift\n  Where the month''s actual work diverged from what FOCUS.md said the focus was. State it\n  neutrally \u2014 drift is sometimes the right call and sometimes the reason nothing shipped.\n\n  ## Stop doing\n  At most three. Things consuming attention with nothing to show: a project with commits but no\n  outcome, a report I never act on, an automation whose output never appears in a decision.\n  Include automations on this schedule \u2014 an unread report is a cost.\n\n  ## Still unexamined\n  Items that appeared in the Unexamined section of two or more weekly reviews. These have now\n  survived a month of being ignored; say what that means.\n\nBUDGET: at most 20 tool calls.\n\nRULES:\n  - Read only the weeklies. If a week''s review is missing, say which and carry on.\n  - No new research. This is a report about my reports.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n\nINPUT CONTRACT \u2014 count what you had before you summarise it:\n  1. This job is one level of a rollup: it reads 4-5 weekly reports and nothing below that. Before\n     writing anything, LIST the input files and COUNT them.\n  2. Put the count in the first line of the report: \"Built from N of weekly/ expected inputs.\"\n     Name the ones that are missing.\n  3. If fewer than half are present, still write the report, but put PARTIAL in its title and\n     say in one line which period has no coverage.\n  4. Never present a partial rollup as a complete one. Every level above this one reads only\n     this file and cannot see what you were missing \u2014 an unmarked gap here becomes a\n     confident falsehood in the quarterly and then in the yearly. Right now the tree is\n     young and this WILL bite: as of 2026-09-02 weekly/ holds 1 file and quarterly/ is empty.\n\n## USE THE KNOWLEDGE BASE TO TEST A THEME, NOT TO GATHER MATERIAL\nThe weeklies stay your only source of material. The ladder works because each level reads\nthe level below, and that is deliberate. But \"a problem that recurred in three different\nprojects\" is a claim about the whole record, and four weekly reviews cannot settle it --\nfrom inside one month, a thing that started last spring and a thing that started on the\n3rd look identical.\n\nSo for AT MOST 3 candidate themes, call `mcp__qdrant__qdrant-qdrant-find` with the theme\nin your own words. The base holds what the daily jobs stored, each point carrying `date`\nand `job` in its metadata, so a hit tells you when the theme was last seen and which job\nsaw it.\n  - Hits from BEFORE this month -> the theme is older than the month. Say since when, and\n    that it is standing rather than new.\n  - Hits only from inside this month -> it is this month''s, not a pattern. Downgrade it.\n  - No hits -> say the base did not corroborate it, and keep the theme only if the\n    weeklies carry it plainly on their own.\n\nRetrieval here is a check on a claim you already hold. It must never introduce a finding\nthe weeklies did not contain -- that is exactly how a ladder collapses back into a pile.\n\n  The embedder is all-MiniLM-L6-v2, which is weak on exact names: a query naming one\n  company, product or paper id can return a topical neighbour instead of the thing you\n  asked for. Measured -- a query for \"DoorDash AI Research Fellowship\" returns a\n  different fellowship that has a more prominent deadline. So judge a hit by READING it,\n  never by its rank, and treat a near-miss as \"not corroborated\" rather than as proof.", "schedule": {"kind": "cron", "cron": "0 7 1 * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-d6306af97d", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-d6306af97d", "task_session_id": "__task__task-d6306af97d", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.916137, "updated_at": 1788372397.796956, "next_run": 1790852400.0, "last_run": 1788260428.3550823, "last_status": "ok", "run_count": 1, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-3c31fb8c75',1,1790854200.0,'{"title": "Quarterly review \u2014 strategy and focus revision", "instructions": "Review the quarter from the three monthly reports, and propose how the focus should\nchange. This is the level where the question stops being \"what happened\" and becomes \"is this\nstill the right thing to be doing\".\n\nREAD: the three monthly reports for the quarter in /home/iconbaypark2900/OpenWorker/knowledge/reports/monthly/, the current\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md, and the previous quarterly in /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/<YYYY>-Q<n>.md:\n\n  ## The quarter in five lines\n  What actually happened. Five lines, no more.\n\n  ## What compounded\n  Work where this quarter built on the last one. This is the only kind of progress that\n  survives; name it precisely and say what made it possible.\n\n  ## What was churn\n  Effort that left nothing behind \u2014 restarts, abandoned directions, the same problem solved\n  twice. Say what it cost in weeks.\n\n  ## Proposed FOCUS.md revision\n  A concrete diff, NOT applied: which Active entries to drop, which Went-quiet entries to\n  formally park, which open questions are answered, and at most one thing to add. Give the\n  reason for each line. I decide whether to take it \u2014 never edit FOCUS.md from this job.\n\n  ## The bet\n  If the next quarter can only advance one of the Active projects, which one and why. Argue\n  for it; a ranked list with no argument is a dodge.\n\nBUDGET: at most 20 tool calls. No new research \u2014 this reads my own reports.\n\nRULES:\n  - Judge from the record, not from what would be encouraging to read.\n  - Three monthlies is the whole input. If one is missing, say so and weight accordingly.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\nTHREADS \u2014 keep the durable record current, not just the dated one:\n  Your dated report is the evidence; the brain''s threads are the memory a future session reads.\n  After writing the report, for each subject that MOVED this run:\n    1. `brain_recall` the subject to find its existing thread \u2014 extend that thread, never fork a\n       near-duplicate of it.\n    2. `brain_note` one entry: what changed, with the specifics, and `source` set to the file you\n       just wrote.\n    3. Pass `now` ONLY if the subject''s current state actually changed. That line is what keeps a\n       stale claim from being retrieved later as if it were still true.\n  A quiet run notes nothing. Inventing movement to have something to record is worse than silence.\n\nINPUT CONTRACT \u2014 count what you had before you summarise it:\n  1. This job is one level of a rollup: it reads 3 monthly reports and nothing below that. Before\n     writing anything, LIST the input files and COUNT them.\n  2. Put the count in the first line of the report: \"Built from N of monthly/ expected inputs.\"\n     Name the ones that are missing.\n  3. If fewer than half are present, still write the report, but put PARTIAL in its title and\n     say in one line which period has no coverage.\n  4. Never present a partial rollup as a complete one. Every level above this one reads only\n     this file and cannot see what you were missing \u2014 an unmarked gap here becomes a\n     confident falsehood in the quarterly and then in the yearly. Right now the tree is\n     young and this WILL bite: as of 2026-09-02 weekly/ holds 1 file and quarterly/ is empty.\n\n## USE THE KNOWLEDGE BASE TO TEST WHETHER A DIRECTION IS ACTUALLY OLD\nThe three monthly reports stay your source of material; the ladder reads the level below.\nBut this level''s question -- \"is this still the right thing to be doing\" -- turns on how\nlong something has been true, and three monthlies cannot see past their own quarter.\n\nFor AT MOST 4 claims that matter to the recommendation, call\n`mcp__qdrant__qdrant-qdrant-find` and look at the `date` on what comes back. An open\nquestion first recorded eight months ago and still open is a fundamentally different\nargument from one raised in November, and the monthlies alone cannot tell you which you\nhave. Say the date you found, and what it changes about the recommendation.\n\nNever let a retrieved point become a finding in its own right. It qualifies a claim the\nmonthlies already made; it does not add one.\n\n  The embedder is all-MiniLM-L6-v2, which is weak on exact names: a query naming one\n  company, product or paper id can return a topical neighbour instead of the thing you\n  asked for. Measured -- a query for \"DoorDash AI Research Fellowship\" returns a\n  different fellowship that has a more prominent deadline. So judge a hit by READING it,\n  never by its rank, and treat a near-miss as \"not corroborated\" rather than as proof.", "schedule": {"kind": "cron", "cron": "30 7 1 1,4,7,10 *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-3c31fb8c75", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-3c31fb8c75", "task_session_id": "__task__task-3c31fb8c75", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9170063, "updated_at": 1788372397.821277, "next_run": 1790854200.0, "last_run": null, "last_status": null, "run_count": 0, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-b5517950bb',1,1798804800.0,'{"title": "Yearly review \u2014 the year in the record", "instructions": "Write the year from the four quarterly reviews. One page. This is the document I read\nwhen deciding what the next year is for, so it has to be honest about the last one.\n\nREAD: the four quarterlies in /home/iconbaypark2900/OpenWorker/knowledge/reports/quarterly/, plus the current\n/home/iconbaypark2900/OpenWorker/knowledge/FOCUS.md.\n\nWRITE /home/iconbaypark2900/OpenWorker/knowledge/reports/yearly/<YYYY>.md, one page, these sections:\n\n  ## What exists now that did not a year ago\n  Concrete artifacts \u2014 shipped systems, published work, capabilities. If the list is short,\n  let it be short.\n\n  ## What I learned\n  Things that changed how I work, drawn from the record rather than sentiment.\n\n  ## What I kept doing that did not work\n  Patterns visible across quarters: the recurring restart, the project that was always almost\n  finished, the report nobody read. A year of data makes these visible in a way a month cannot.\n\n  ## The through-line\n  In one paragraph: what was this year actually about? Not the plan \u2014 the evidence.\n\n  ## Next year''s question\n  The single question the next year should answer. One question, argued for.\n\nBUDGET: at most 15 tool calls. No new research.\n\nRULES:\n  - Four quarterlies in, one page out. Compression is the deliverable.\n  - Do not flatter the record. An honest bad year is more useful than a padded one.\n\nSHELL RULES \u2014 you are unattended, so keep every command small and reviewable:\n  - NEVER inline a multi-line script (no heredocs). Write it to a file with write_file, then\n    run that file.\n  - One command does one thing. Cap output: head, tail -n, wc -l, --quiet.\n  - Use native paths (/home/iconbaypark2900/...). The filesystem MCP server sees this machine''s\n    home as /data/home instead, so its paths and shell paths are NOT interchangeable \u2014 prefer\n    shell for files, and only use qdrant through MCP.\n  - /home/iconbaypark2900/OpenWorker/knowledge is a WRITABLE ROOT of this session. Use the normal file\n    tools on it with absolute paths \u2014 read_file, write_file, list_files all work there, and\n    they are more reliable than shell redirection. Shell is for git, sqlite, find and curl.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\nINPUT CONTRACT \u2014 count what you had before you summarise it:\n  1. This job is one level of a rollup: it reads 4 quarterly reports and nothing below that. Before\n     writing anything, LIST the input files and COUNT them.\n  2. Put the count in the first line of the report: \"Built from N of quarterly/ expected inputs.\"\n     Name the ones that are missing.\n  3. If fewer than half are present, still write the report, but put PARTIAL in its title and\n     say in one line which period has no coverage.\n  4. Never present a partial rollup as a complete one. Every level above this one reads only\n     this file and cannot see what you were missing \u2014 an unmarked gap here becomes a\n     confident falsehood in the quarterly and then in the yearly. Right now the tree is\n     young and this WILL bite: as of 2026-09-02 weekly/ holds 1 file and quarterly/ is empty.\n\n## USE THE KNOWLEDGE BASE TO DATE THE YEAR''S CLAIMS\nThe four quarterlies stay your source. Use `mcp__qdrant__qdrant-qdrant-find` for AT MOST\n3 lookups, for one purpose only: when you are about to write that something ran all year,\nor first appeared this year, check the base for the earliest point that says so and give\nthe real date. A year summary that misdates its own beginnings is the one error here that\ncompounds, because next year reads this file and not the record.\n\n  The embedder is all-MiniLM-L6-v2, which is weak on exact names: a query naming one\n  company, product or paper id can return a topical neighbour instead of the thing you\n  asked for. Measured -- a query for \"DoorDash AI Research Fellowship\" returns a\n  different fellowship that has a more prominent deadline. So judge a hit by READING it,\n  never by its rank, and treat a near-miss as \"not corroborated\" rather than as proof.", "schedule": {"kind": "cron", "cron": "0 8 1 1 *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-b5517950bb", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-b5517950bb", "task_session_id": "__task__task-b5517950bb", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9178355, "updated_at": 1788372397.823495, "next_run": 1798804800.0, "last_run": null, "last_status": null, "run_count": 0, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-9b2a9d143b',1,1788687900.0,'{"title": "Revenue \u2014 ways to earn with the agent stack", "instructions": "Find money I can earn by SUBMITTING WORK, never by submitting an\napplication. Rank by TIME TO FIRST PAYMENT - days from starting to money in the bank.\n\n## WHY THIS JOB IS NARROW NOW. READ THIS BEFORE SEARCHING.\nThe discovery side of this house works and the conversion side does not. The application\nledger records 77 drafts written and exactly ONE application ever sent (Sprinter Health,\n2026-09-01, confirmation seen). The blockers are structural, not effort: real forms run 15\nrequired fields and 7 dropdowns against an 8-field auto-fill threshold, and two of five\ntargets had CLOSED between being discovered and being applied to.\n\nSo more job leads are worth nothing right now. What is worth something is money that has\nno application form in front of it at all: you do a piece of work, submit it, it is scored\nor triaged, you get paid. That is the entire scope of this job.\n\n## IN SCOPE - the only things you may report\n[BOUNTIES - SECURITY AND AI SAFETY] Submit a finding, it is triaged, it pays. huntr,\n  HackerOne, Bugcrowd, Immunefi, Mozilla 0din, vendor VRPs, and the AI-lab model-safety\n  programmes (Anthropic''s, OpenAI''s and their equivalents). This is the closest match to\n  what I do all day - dcode-stack is a harness built to contain agents, and these pay for\n  breaking them.\n[STANDING RED-TEAM AND EVAL PROGRAMMES] Recurring paid panels for breaking or grading AI\n  systems. Getting accepted once pays repeatedly. Report the intake step honestly: a\n  written test or an automated assessment is IN SCOPE; a scheduled call with a person is\n  NOT, and disqualifies the entry.\n[COMPETITIONS AND CONTESTS] Open submission window, real prize pool, automated or panel\n  scoring. Kaggle, ARC Prize, AICrowd, mlcontests.com, arena-style contests, quantum\n  challenges (IBM Quantum, Xanadu/QHack, Unitary Foundation, apartresearch.com).\n  Quantum is a thin field and that thinness is the advantage - check it every run.\n[SELL AN ARTIFACT] Publish once, get paid repeatedly, never speak to a buyer. HuggingFace\n  paid collections and inference revenue share, Replicate payouts, Gumroad or Lemon\n  Squeezy for eval suites and datasets, Polar.sh on a funded repo. Name the artifact I\n  could ship THIS WEEK from what is already on this machine, and name the nearest free\n  alternative. If the honest answer is \"the free alternative is good enough\", say that.\n[OPEN-SOURCE BOUNTIES] A merged pull request pays. Algora, Polar.sh, thanks.dev,\n  OpenCollective-funded issues, repos labelled `bounty`.\n[COMPUTE CREDITS] Credits are cash I would otherwise spend. NVIDIA Inception, Modal,\n  Lambda, Together, Fal, Baseten research credits. THE FILTER THAT MATTERS is \"no\n  institution required\" - a 09-04 run already established that GCP TPU Research Cloud and\n  Google research credits require faculty/PhD/postdoc affiliation and are a dead end for a\n  solo individual. Do not re-check those; check whether anything new has opened.\n\n## OUT OF SCOPE - do not report these, however good they look\n- Job openings, roles, and anything with an application form or an ATS.\n- Fellowships and residencies that are applied to rather than submitted to. The\n  Fellowship & residency finder automation already covers those; duplicating it here\n  feeds the queue that is already 77 deep.\n- Contract and freelance work, Upwork/Contra/Braintrust, and anything with a client.\n- Expert networks and paid consultation calls - GLG, AlphaSights, Guidepoint, Third\n  Bridge, Dialectica, Coleman. Their entire product is hour-long calls with strangers.\n- Dropshipping, affiliate schemes, content farming, prompt selling, any course about\n  making money, anything needing capital I do not have, and anything whose only evidence\n  is a blog post claiming someone made money.\nIf a whole track returns only out-of-scope results, say the track was empty this run. That\nis a real finding and it stops the next run spending budget there.\n\n## EVERY ENTRY NEEDS\n- Name, URL, and EVIDENCE THAT MONEY CHANGES HANDS: a posted bounty amount, a published\n  rate card, a paid-out leaderboard, a prize pool with rules, a documented payout ledger.\n  \"Can be lucrative\" is not evidence.\n- TIME TO FIRST PAYMENT in days, with the assumption behind it (triage lag, payout terms).\n- WHAT I ACTUALLY SUBMIT - the concrete artifact, in one sentence, READ FROM THE RULES OR\n  TASK-FORMAT PAGE. A fit claim requires reading what the task is. An earlier run called\n  ARC-AGI-2 \"your exact domain (QSVC/KG)\" when it is abstract visual grid reasoning with\n  pixel-exact integer output, sharing no structure, format or objective with knowledge-\n  graph link prediction; acting on it would have cost days. If you cannot reach the format\n  page, mark the fit UNVERIFIED and name the page you could not open.\n- THE INTAKE STEP, stated plainly: nothing, a written test, or an automated assessment.\n  If it turns out to require a call with a person, the entry is out of scope - drop it.\n- Whether I can meet it TODAY with no entity, no institution, no degree and little\n  capital. Be blunt where I cannot.\n- The first concrete action I would take in the next hour.\n\n## THE TRACKER IS READ-ONLY FOR YOU\n`opportunities.md` is staged into your workspace. READ it: anything already listed is not\na fresh find, so re-verify its state and report only what CHANGED. Do NOT rewrite it. The\ncanonical copy lives in ~/OpenWorker/apply/ and staging is one-way, so anything you write\nto your copy is discarded at the next staging pass and would be silently lost. If you find\nsomething new that carries a deadline, put it under a clearly marked heading\n\"## NEW - CARRIES A DEADLINE\" at the top of your report so it can be folded in by hand.\n\n## BUDGET AND OUTPUT\nAt most 12 web searches. Go to the boards themselves; generic searches return the same\nfour results and then SEO farms. Prefer the programme''s own rules page over any write-up\nabout it.\n\nFIVE real findings beat twenty padded ones. If the week is thin, return three and say so.\n\nWrite revenue-latest.md, OVERWRITING it every run. Do NOT date-stamp the filename: earlier\nruns wrote four files inside ninety minutes dated up to three days into the future, growing\nfrom 12KB to 24KB. Order by time to first payment, soonest first. Writing this file is the\nrun''s final action and the run is not finished until it exists.\n\nCONTINUITY & FOCUS - two reads, before anything else:\n  1. read_file FOCUS.md in your workspace. It is staged there now; earlier runs opened with\n     \"FOCUS.md STILL ABSENT\" and hand-tagged from nothing, because the stager only ever\n     copied it to the Apply automation. Fixed 2026-09-02. Its first line names the week\n     (\"# FOCUS - week of YYYY-MM-DD\"); if that is more than 8 days old, say so in one line\n     and treat its ranking as weak evidence. Tag each finding ON-FOCUS or ADJACENT, lead\n     with ON-FOCUS, cap ADJACENT at three and put them last.\n  2. read_file your previous revenue-latest.md. Carry forward what is still open, mark what\n     has closed or been won, and spend this run on what is genuinely NEW. Say \"X, first\n     seen <date>, is now <state>\" rather than re-reporting X as fresh. Never re-report an\n     unchanged item as a new finding - four consecutive runs returned the same seven\n     things, and that is what made them worthless.", "schedule": {"kind": "cron", "cron": "45 5 * * 4,0", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-9b2a9d143b", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-9b2a9d143b", "task_session_id": "__task__task-9b2a9d143b", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["read_file", "read_file_lines", "list_files", "grep", "write_file", "todo_write", "remember", "brain_note", "brain_recall", "web_search", "web_fetch"], "always_allowed_commands": [], "enabled": true, "created_at": 1788309759.364038, "updated_at": 1788429083.343419, "next_run": 1788687900.0, "last_run": 1788428706.103096, "last_status": "ok", "run_count": 6, "max_runs": null, "seen_runs_at": 0.0}');
INSERT INTO scheduled_tasks VALUES('task-f471043f3e',1,1788596100.0,'{"title": "CI sweep - tests, environments and stack drift", "instructions": "Report on the health of the code and the stack on this machine, from\nevidence gathered by the sweep that runs 30 minutes before you.\n\nWHAT THIS JOB IS. It is CI for a box that has none, plus the weekly record of what moved,\nplus the spec-conformance audit. Forgejo runs here but has no Actions runner, and every\nworkflow file targets `runs-on: ubuntu-latest`, so nothing on this machine has ever run\nits own tests. The sweep now does: ~2,300 tests across five repos, a git pass over eleven,\nand a spec manifest over ten dcode-stack slices. You read the results and decide what\nmatters. You do not gather; gathering already happened.\n\nWHAT THIS JOB IS NOT, any more. It used to be a research task with no shell whose watch\nlist was a hardcoded string describing AMD ROCm hardware on gfx1151/Strix Halo. This box\nis an NVIDIA GB10 on aarch64 and has never had ROCm; 21 runs went into release notes for\na machine that does not exist. Never carry a version number in from memory or from a\nprevious report''s prose. Every fact about this machine comes from inventory.md.\n\n## READ FIRST, IN THIS ORDER\n  1. ci-results.md     - per-repo test outcome table. Primary evidence.\n  2. spec-manifest.md  - the ten slices, this run''s three audit targets, mechanical\n                         findings, and the open findings carried forward with their age.\n  3. repo-activity.md  - commits by you in the last 7 days, plus a needs-attention table.\n  4. inventory.md      - what is actually installed and running, generated this morning.\n  5. Your previous ci-report-<older date>.md.\n\n## OUTCOMES ARE THREE-WAY. THE RULE THAT MATTERS MOST.\nPASS and FAIL both mean the suite RAN. Everything else - COLLECT_ERROR, TIMEOUT,\nNO_RUNNER, NO_TESTS, MISSING - means it DID NOT RUN and must never be reported as healthy.\nA repo showing COLLECT_ERROR may still print a `passed` count; that number is not a green\nlight, because the modules that failed to import contributed nothing to it. Say \"did not\nrun\", not \"no failures found\". The same applies to a slice you did not read: UNKNOWN, not\nOK. A check that cannot tell \"it broke\" from \"it never ran\" is not a check.\n\n## WHAT TO REPORT, IN THIS ORDER\n1. REGRESSIONS - PASS last week, not PASS now. Name the repo and the failing tests.\n2. STILL RED - failures carried from last week, with how many weeks they have been red.\n3. DID NOT RUN - every non-PASS/FAIL outcome, with its reason.\n4. SPEC DRIFT - see the section below. Open findings first, with age, then new ones.\n5. WORK THAT EXISTS ONLY ON THIS DISK - from repo-activity.md''s needs-attention table:\n   every repo with unpushed commits, and any with a large dirty count. Do NOT push and do\n   not offer to; the ~/.githooks pre-push policy gates that deliberately.\n6. WHAT MOVED - a short narrative of the week''s real work from the commit lists. Lead with\n   the project FOCUS.md ranks highest. Say what a change accomplishes rather than\n   restating its subject line. Cap it at the three or four repos that actually moved.\n7. STALLED - only what the needs-attention table flags. Silence is the normal case.\n8. STACK DRIFT - only now, and only against inventory.md, check upstream for advisories or\n   breaking changes affecting the versions actually listed there. AT MOST 4 web searches.\n   Cite the advisory URL you opened. Skip the section rather than pad it.\n\n## SPEC CONFORMANCE\nTests check what someone thought to test. The spec is what was promised. These come apart:\non 2026-09-02 dcode-stack passed 274 tests while violating its own SPEC R9 - trial-counter\nguards with `isinstance(sharpe, (int, float))`, and `isinstance(True, int)` is True in\nPython, so `record_outcome(id, True)` stores a Sharpe of 1.0. The suite contains zero\nreferences to bool or True, so CI is green and cannot see it. That is the gap this covers.\n\nMETHOD, for the THREE targets spec-manifest.md names - and only those three:\n  1. Re-verify every OPEN finding the manifest carries. State whether it is still present,\n     and its age. An open finding gets LOUDER with age, never quieter, and is never\n     re-reported as a fresh discovery.\n  2. For each target: read the SPEC.md, then the implementation. Both, in full. The paths\n     are already in the manifest - do not spend calls finding them.\n  3. Compare. What does the requirement demand, what does the code do, do they agree?\n  4. Prefer a live probe over reading where a probe is cheap: `python3 -c` on a boundary\n     value settles in one call what a paragraph of reasoning leaves arguable.\n  5. Record what you actually audited in spec-audit-state.json as {\"<slice>\": \"<date>\"} so\n     the rotation advances. A slice you did not genuinely read must NOT be recorded -\n     recording it hides it for weeks.\n\nFAIL CLOSED. Could not read it, could not run it, ran out of budget: that slice is UNKNOWN.\nAn unverified claim of conformance is worse than admitting you did not check, because it\ngets trusted. Three slices audited properly beats ten skimmed.\n\nPRIORITISE the invariants these specs care about, which are mostly about silent failure:\nmalformed input that must be fatal rather than coerced, guards that must not be dropped,\nvalues that must raise rather than default.\n\nNote for TypeScript slices: node on this box does not compile .ts, so a .ts slice can be\nverified by reading but NOT by execution. Say which you did. That distinction is the whole\nvalue of the report.\n\n## YOU MAY DO THREE THINGS. NOTHING ELSE.\n\n### (a) Repair an environment\nWhen a repo shows COLLECT_ERROR because its own venv lacks a dependency THAT REPO ITSELF\nDECLARES: read the declaration (pyproject.toml [project] dependencies, or requirements.txt),\ninstall it into that repo''s OWN venv with `<repo>/.venv/bin/python -m pip install \"<spec>\"`,\nre-run that suite, and report before/after counts. The reference case: agpack declared\n`pydantic>=2` and `cryptography>=42` and had neither, so four modules could not import;\ninstalling them took it from 165 passing with 4 dead modules to 276 with none.\n\n### (b) Write a FAILING TEST for a confirmed spec violation\nOnly for a violation you have CONFIRMED this run by reading both sides AND observing the\nbehaviour with a probe. Never for one you merely suspect.\n\n  PRECONDITION - check it and obey it:\n    `git -C <repo> status --porcelain` must be EMPTY. If the tree is dirty, do NOT touch\n    the repo: write the test into your own workspace as `proposed-test-<slice>.py`, say so\n    in the report, and stop. A dirty tree means work in progress that is not yours to\n    disturb.\n\n  THEN, exactly this, and nothing more:\n    git -C <repo> rev-parse --abbrev-ref HEAD          # remember the branch you started on\n    git -C <repo> checkout -b spec-drift/<slice>-<YYYY-MM-DD>\n    ... write ONE NEW test file. Never edit an existing test file, ever ...\n    git -C <repo> add <the one new file>\n    git -C <repo> commit -m \"<slice>: failing test for <requirement> (spec drift)\"\n    git -C <repo> checkout <the branch you started on>\n  Then run the new test once to prove it FAILS, and report that it fails. A test that\n  passes has not captured the bug and is worse than none - delete it and say so.\n\n  If any step errors, run `git -C <repo> checkout <original branch>` immediately, report\n  what happened, and change nothing else. Leaving the repo on a stray branch is the one\n  outcome worse than not writing the test.\n\n  Record it in spec-findings.json with \"test_written\": true and the branch name.\n\n### FORBIDDEN, without exception\n  - Editing any implementation file, or any existing test, for any reason.\n  - Making a failing test pass. You capture the bug; you do not fix it.\n  - Installing anything a repo does not already declare, or into the system python.\n  - Upgrading a package that is installed and working.\n  - `git push`, any deploy, and any commit outside the spec-drift branch above.\nIf a fix needs something on this list, WRITE IT DOWN with the exact command you would have\nrun, and stop.\n\n## NEVER READ GITHUB FOR ANY OF THIS\nOrigin is the self-hosted Forgejo at git.home.arpa:2222. The github.com copies are stale\nmirrors - dcode-stack''s was 11 days behind and agpack has no GitHub repo at all. The\npredecessor job asked the GitHub MCP for commits and spent its last five runs getting\nnothing, first on `fetch failed` then `Bad credentials`, while still finishing \"ok\".\n\n## BUDGET\nAt most 30 shell calls and 4 web searches. Tests are already run, commits already\ncollected, specs already located. If you are writing a Python script to do any of this,\nyou have taken the wrong path: stop and use one-line shell commands with output capped.\n\n## OUTPUT\nWrite ci-report-$(date +%F).md - take the date from the shell, never from memory. Lead with\nthe single most important line: the regression, or the spec violation, or else \"no\nregressions; N repos PASS, M did not run, K commits unpushed, S slices audited clean\". If\neverything is green, say so in a few lines. A short honest report is the correct output for\na quiet week, and padding it is worse than silence.\n\nCONTINUITY & FOCUS - two reads, before anything else:\n  1. read_file FOCUS.md in your workspace. Its first line names the week it was written for\n     (\"# FOCUS - week of YYYY-MM-DD\"). Tag findings ON-FOCUS or ADJACENT; lead with\n     ON-FOCUS. A red suite or a spec violation in the project FOCUS.md ranks first is the\n     most important line in your report. If the week named is more than 8 days old, say so\n     in one line and treat its ranking as weak evidence. Missing fails loudly, stale fails\n     silently, and stale is what actually happens.\n  2. list_files your workspace and read your previous ci-report. Carry forward what is\n     still red, mark what has gone green, and say \"X, red since <date>, now passes\" rather\n     than re-reporting it as new. The value is the running record.", "schedule": {"kind": "cron", "cron": "15 4 * * 6", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-f471043f3e", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-f471043f3e", "task_session_id": "__task__task-f471043f3e", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786987187.2846577, "updated_at": 1788454706.933278, "next_run": 1788596100.0, "last_run": 1788365705.5386827, "last_status": "ok", "run_count": 21, "max_runs": null, "seen_runs_at": 1788454706.9332764}');
INSERT INTO scheduled_tasks VALUES('task-1b2c4d3f13',1,1788595200.0,'{"title": "Research papers \u2014 quantum, ML, recursive self-improvement", "instructions": "Find research papers published in the last 24 hours across three topics:\n1. Quantum computing \u2014 algorithms, error correction, hardware, quantum ML.\n2. Machine learning \u2014 architectures, training methods, reasoning, evaluation.\n3. Recursive self-improvement \u2014 self-modifying agents, automated AI research, models that improve their own capabilities, scaling of autonomous research loops.\n\nHOW TO SEARCH \u2014 this matters, read it before starting:\nUse the arxiv MCP tools directly: search_papers to find candidates, get_abstract to read them, semantic_search when a keyword query is too blunt. They are already connected and need no setup.\n\nDo NOT write a Python script, and do NOT use run_shell or curl to query the arXiv API. You are running unattended on a schedule: every shell command stops and waits for a human to approve it, so a script-based approach stalls this run indefinitely and produces nothing. The MCP tools do not require approval. If an arxiv tool returns nothing useful, use the web search tool \u2014 never fall back to shell.\n\nFor each paper give: title, authors, link, and 2-3 sentences on what is genuinely new and why it matters \u2014 your own read, not the abstract restated.\n\nBe selective. Skip incremental variations. If a topic has nothing genuinely new today, say so in one line rather than padding the list.\n\nSave the result as papers-YYYY-MM-DD.md in the task workspace, grouped by the three topics, most significant first within each. Writing that file is the deliverable \u2014 do not finish the run without it.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n", "schedule": {"kind": "cron", "cron": "0 4 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-1b2c4d3f13", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-1b2c4d3f13", "task_session_id": "__task__task-1b2c4d3f13", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900126.999427, "updated_at": 1788509052.911544, "next_run": 1788595200.0, "last_run": 1788508806.8814456, "last_status": "ok", "run_count": 25, "max_runs": null, "seen_runs_at": 1788451011.9155567}');
INSERT INTO scheduled_tasks VALUES('task-c6cf366b90',1,1788597300.0,'{"title": "Fellowship & residency finder", "instructions": "Find FELLOWSHIPS, RESIDENCIES AND PROGRAMMES worth applying for, based on my resume.\nStandard job openings are now SECONDARY \u2014 report at most three, and only if they are an\nunusually strong fit. The applicant has redirected this pipeline at fellowships and grants.\n\nWHY THE EMPHASIS CHANGED: fellowships close on a DATE, not when a role is filled, so a\nmissed window cannot be recovered. Six fellowships already have tailored drafts on file\n(GovAI, AIAF, ADF, CTEC, CSC Generation, Lila Sciences) and NOT ONE has had its deadline\nchecked. Cambridge ERA:AI and MATS were both open for weeks before anything noticed.\nChecking whether a known programme''s window is open is worth more than finding a new job.\n\nYour resume is staged in your own workspace as resume.txt (plain text, already extracted from the PDF) \u2014 read it with your file tools, by that plain filename, and use it to establish background, seniority, technical domain and eligibility.\n\nDo NOT use run_shell, ls, cat, curl or a Python script, and do not try to reach into ~/Documents/ \u2014 you run unattended and cannot see outside this workspace, so any shell command stops the run to wait for a human and nothing gets written. Web search IS allowed and needs no approval.\n\nWORK, DON''T NARRATE: do not end your turn to describe what you are about to do. Carry each step through. The run is not finished until the output file exists in this workspace \u2014 write it as your final action, every time, even if some step failed. A file that records \"search returned nothing useful for X\" is a success; no file at all is a failure.\n\nFIRST, BEFORE ANY NEW SEARCH \u2014 check the ones already drafted.\n\nThese have tailored cover letters in drafts/ and their deadlines have NEVER been verified.\nFor each, find the official programme page and report: is the window OPEN, and if so what\nis the exact deadline?\n\n  GovAI (Centre for the Governance of AI)   drafts/cover-letter-govai.md\n  AIAF                                      drafts/cover-letter-aiaf.md\n  ADF                                       drafts/cover-letter-ADF.md\n  CTEC                                      drafts/cover-letter-CTEC.md\n  CSC Generation                            drafts/cover-letter-csc-generation.md\n  Lila Sciences                             drafts/cover-letter-lilasciences.md\n  MATS Residency (Winter 2027)              drafts/cover-letter-MATS.md \u2014 believed open, Oct 31\n\nReport each as OPEN (with the deadline and apply URL), CLOSED (with the date it closed and\nwhen the next cycle opens), or UNVERIFIABLE (say what you could not confirm). An open one\nwith a near deadline outranks anything new you might find.\n\nWHAT TO SEARCH FOR \u2014 two categories, both are positions you hold and get paid for:\n1. Standard openings matching the profile \u2014 seniority, domain, technical strengths.\n2. Fellowships and residencies that function as jobs: AI/ML residencies, research fellowships with a salary or stipend, industry fellowships, government and think-tank technical fellowships. Include these even when the title says \"fellow\" rather than \"engineer\".\n\nDo NOT include funding-only fellowships here \u2014 grants that pay for your own independent work, with no employer, belong to the separate weekly grant digest. The test is simple: if you would be working *for* an organisation, it goes here; if you would be receiving money to pursue your own project, it does not.\n\nSearch openings posted in roughly the last 7 days, plus every fellowship, residency or programme whose application window is OPEN right now regardless of when it was posted \u2014 those close on a date, not on a posting age, and a one-day window kept missing them. The applier downstream can only file what this run finds; a thin list here is the binding constraint on the whole pipeline, not a saving.\n\nFor each match record: organisation, role title, whether it is a standard role or a fellowship/residency, location and remote policy, salary or stipend if stated, link, and a fit assessment naming the specific evidence in my resume that supports it plus any genuine gaps against the requirements. Fellowships often have fixed cohort deadlines \u2014 record the deadline whenever one exists, since those close on a date rather than when filled.\n\nRank by fit and keep only plausible matches, but report EVERY one that is genuinely open and plausible \u2014 aim for 10-15 where they exist. Padding with bad fits is still wrong; withholding a real match because three felt like enough is worse, because nothing downstream can apply to what you did not list.\n\nFor the top 6 matches, create a drafts/ subfolder containing, per role:\n- cover-letter-<organisation>.md \u2014 tailored to that specific posting, using real evidence from the resume and referencing what the organisation actually does.\n- resume-tweaks-<organisation>.md \u2014 specific edits that would strengthen this application: which bullets to lead with, what to rephrase in the posting''s language, what to cut.\n\nNever invent experience, credentials, or dates that are not in the resume.\n\nSave the shortlist as jobs-YYYY-MM-DD.md, fellowships and standard roles clearly labelled. Do not submit an application anywhere or contact anyone \u2014 produce the files only.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n\n## THE TRACKER \u2014 read it first, update it last\n\n`opportunities.md` is staged in your workspace. It is the single list of everything with\na live deadline, and it exists because GovAI and AIAF both closed in August with tailored\ncover letters already written and nobody watching the date.\n\nBEFORE searching: read it. Anything already listed is NOT a fresh find \u2014 re-verify its\nstate instead (still open? deadline moved? closed?) and report the CHANGE, nothing more.\nSpend the search budget on what is genuinely new.\n\nAFTER searching: rewrite `opportunities.md` with write_file, carrying every existing row\nforward and adding what you found. Put anything with a date in the deadline table sorted\nsoonest-first, anything rolling in the rolling table, and move whatever has closed into\nthe closed table rather than deleting it \u2014 a closed row is what stops it being\nrediscovered next week. Never drop a row you did not verify as closed.\n", "schedule": {"kind": "cron", "cron": "35 4 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-c6cf366b90", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-c6cf366b90", "task_session_id": "__task__task-c6cf366b90", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786900127.0179763, "updated_at": 1788511415.927253, "next_run": 1788597300.0, "last_run": 1788510906.8980403, "last_status": "ok", "run_count": 25, "max_runs": null, "seen_runs_at": 1788451006.7529838}');
INSERT INTO scheduled_tasks VALUES('task-c685e22a0b',1,1788600000.0,'{"title": "Morning news briefing", "instructions": "Write me a 5-bullet briefing on what actually happened in the last 24 hours.\n\nSCOPE \u2014 in priority order. Lead with whatever genuinely moved:\n  1. AI / ML industry: model releases, capability results, major funding and\n     acquisitions, compute and chip supply, notable safety or policy incidents.\n  2. Local-inference and open-weights specifically: llama.cpp / ollama / vLLM,\n     new open weights, quantization and hardware support (AMD ROCm especially \u2014\n     this machine runs a Strix Halo iGPU).\n  3. World news that a US-based engineer should not be blindsided by: major\n     geopolitical events, market-moving macro, significant policy changes.\n\nMETHOD:\n  1. web_search for each of the three areas separately \u2014 do not merge them into one\n     query, the results collapse into whatever is loudest.\n  2. web_fetch and actually READ at least two sources before writing. A search snippet\n     is a pointer, not evidence.\n  3. Prefer the primary source (the release post, the filing, the announcement) over\n     an aggregator reporting on it.\n\nBUDGET: AT MOST 5 searches and 4 page fetches.\n\nFOR EACH BULLET: one bold claim sentence, then the specific detail that makes it matter\n(the number, the name, the date), then the source in parentheses. Attribute every\nnon-obvious figure to a page you actually opened.\n\nRULES:\n  - Exactly 5 bullets. If the day is genuinely thin, say so in one line and give 3 \u2014\n    padding a slow day with filler makes the briefing worthless to skim.\n  - Never state a figure, date, or version you did not read directly. No reconstructing\n    plausible headlines from memory.\n  - Skip anything you already reported in a prior briefing unless it materially changed.\n\nSave as morning-briefing-YYYY-MM-DD.md. Writing that file is the deliverable \u2014 a run\nthat ends without it has failed.\n\nCONTINUITY \u2014 do this FIRST, before any searching:\n  1. list_files in your workspace and read the 1-2 most recent prior outputs of this\n     same job (they share this file-naming pattern).\n  2. Carry forward what is still live, mark what has closed or been resolved, and spend\n     your search budget on what is genuinely NEW since then.\n  3. If something you reported before has changed state, say so explicitly \u2014 \"X, first\n     flagged <date>, is now <state>\" is worth more than rediscovering X as if it were new.\n  4. Never re-report an unchanged item as a fresh finding.\nThis job runs on a schedule and its outputs accumulate; the value is in the running\nrecord, not in a fresh cold start every time.\n\nFOCUS \u2014 do this before anything else:\n  1. read_file FOCUS.md in your own workspace. It is rewritten every Monday from what I\n     actually worked on: the projects in play, the open questions, and what I have parked.\n  2. Tag every item you report ON-FOCUS or ADJACENT. ON-FOCUS bears on a project or open\n     question named in FOCUS.md; ADJACENT does not, but is worth knowing anyway.\n  3. Lead with ON-FOCUS. Keep the ADJACENT ones \u2014 being shown only what I already care about\n     is exactly how I get stuck \u2014 but cap them at three and put them last.\n  4. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n  5. STALENESS. Its first line names the week it was written for (\"# FOCUS \u2014 week of\n     YYYY-MM-DD\"). Compare that to today. More than 8 days old means the Monday job that\n     rewrites it did not run, and you are sorting by a dead focus. Say so in one line at the\n     top of your output and treat its items as weak evidence, not current priority. A file\n     that exists is not a fresh file \u2014 missing fails loudly, stale fails silently, and stale\n     is the one that actually happens.\n", "schedule": {"kind": "cron", "cron": "20 5 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-c685e22a0b", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-c685e22a0b", "task_session_id": "__task__task-c685e22a0b", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1786891896.2770672, "updated_at": 1788513881.169202, "next_run": 1788600000.0, "last_run": 1788513606.9264333, "last_status": "ok", "run_count": 26, "max_runs": null, "seen_runs_at": 1788450950.7136822}');
INSERT INTO scheduled_tasks VALUES('task-ecad448aa3',1,1788602400.0,'{"title": "Knowledge base \u2014 ingest yesterday''s findings", "instructions": "Put yesterday''s automation findings into the Qdrant knowledge base so the weekly,\nmonthly and quarterly reviews can retrieve them by meaning. Those jobs are the consumers -\nthis job exists for them, not for its own sake.\n\nSTOP WRITING PYTHON. Previous runs wrote 12-17KB store_*.py scripts and scroll_check*.sh\nhelpers every night and took a median 39 minutes - about 40% of the day''s GPU budget - to\nstore a handful of points. The Qdrant MCP tools work now; the base holds 72 points. Call\nmcp__qdrant__qdrant-qdrant-store DIRECTLY, once per finding. If you find yourself writing a\nscript to do this, you have taken the wrong path: stop and use the tool.\n\nFIND the new outputs, in one shell call:\n  find /home/iconbaypark2900 -maxdepth 3 -path ''*__task__*'' -name ''*.md'' -mtime -1 | head -10\nWorkspaces live under BOTH ~/OpenWorker and ~/openworker-tasks - never assume one base.\nSkip FOCUS.md; it is a copy, not a finding.\n\nPER FILE: read_file it and pull AT MOST 6 discrete findings - a claim that would still be\nworth retrieving in three months, carrying its identifier (arXiv id, repo name, version,\nURL) inside the sentence. Not section headings, not \"nothing new today\".\n\nSTORE each with mcp__qdrant__qdrant-qdrant-store:\n  information: one self-contained sentence. Retrieval returns it alone, with no surrounding\n               context, so it must stand on its own.\n  metadata:    {\"job\": \"<source automation title>\", \"date\": \"<YYYY-MM-DD from date +%F>\",\n                \"cadence\": \"daily\", \"focus\": \"on|adjacent\",\n                \"kind\": \"paper|breakage|repo|grant|job|news|analysis\",\n                \"source\": \"<absolute path of the file it came from>\"}\n\nDEDUP ONLY WHERE IT PAYS: a finding from a file written today cannot already be in the base -\nstore it directly and spend no find call. Use qdrant-find only for a finding you suspect\nrestates something older. The old unconditional find-then-store doubled every finding''s cost.\n\nBUDGET: at most 25 stores and 8 finds. Store ON-FOCUS findings first and say in the ledger\nwhat you left behind.\n\nLEDGER: write /home/iconbaypark2900/OpenWorker/knowledge/ingest/$(date +%F).md - a table of\nfile, findings stored, findings skipped as duplicates. mkdir -p the directory first. End with\nthe running total from:\n  curl -s http://127.0.0.1:6333/collections/default | head -c 200\n\nHOUSEKEEPING, first run only: your workspace has accumulated store_*.py, scroll_check*.sh and\nan orphan ledger_2026-09-01.stage from the old approach. Delete them, and never recreate that\npattern.\n\nRULES:\n  - Store only what you read in a file today. Never from memory, never a finding you inferred\n    rather than read - the KB is retrieved as fact later.\n  - A file that says \"nothing new\" produces zero points. That is a correct outcome.\n  - The markdown files stay the source of truth. Qdrant holds the retrievable claim and a\n    path back to the file; it is an index, not a replacement.\n\nSHELL: one command does one thing, output always capped (head, tail -n, wc -l). Never inline\na heredoc. Use native /home/iconbaypark2900/... paths in shell - the filesystem MCP server\nsees this home as /data/home, so its paths and shell paths are NOT interchangeable.\n\nCONTINUITY & FOCUS \u2014 two reads, before anything else:\n  1. read_file FOCUS.md in your workspace. Its first line names the week it was written for\n     (\"# FOCUS - week of YYYY-MM-DD\"). Tag each item ON-FOCUS (bears on a project or open\n     question named there) or ADJACENT. Lead with ON-FOCUS; cap ADJACENT at three and put\n     them last. If FOCUS.md is missing, say so in one line and treat everything as ADJACENT.\n     If the week it names is more than 8 days old, the Monday job that rewrites it did not\n     run: say so in one line at the top and treat its items as weak evidence, not current\n     priority. Missing fails loudly, stale fails silently, and stale is the one that happens.\n  2. list_files your workspace and read your own most recent prior output. Carry forward what\n     is still live, mark what has closed, and spend this run on what is genuinely NEW. Say\n     \"X, first flagged <date>, is now <state>\" rather than rediscovering X. Never re-report\n     an unchanged item as a fresh finding. The value is the running record, not a cold start.\n\n## WRITE THROUGH MCP ONLY. NEVER THROUGH HTTP OR fastembed.\nThis is not a style preference, it is the correctness rule for this job.\n\nThe collection has ONE named vector, `fast-all-minilm-l6-v2`, and that name is the model\n`mcp-server-qdrant` embeds QUERIES with. Earlier runs of this job could not reach the MCP\ntools -- QDRANT_URL pointed at the docker default-bridge gateway while mcp-gateway runs\non librechat_default -- and fell back to a hand-rolled HTTP path using fastembed with\n`BAAI/bge-small-en-v1.5`. That model also emits 384 dimensions, so every write SUCCEEDED\nSILENTLY into a slot named for a different model, and all 72 points became unretrievable:\nnear-verbatim queries returned the wrong document every time. It was repaired on\n2026-09-02 by re-storing all 72 through MCP.\n\nSo: if `mcp__qdrant__qdrant-qdrant-store` is unavailable or returns an error, STOP AND\nSAY SO in the ledger. A run that stores nothing and reports why is a good run. A run that\nroutes around the broken tool with curl or a Python client silently corrupts the base for\nevery future query, and nothing will alert you, because a 384-dim write always succeeds.\nDo not write your own embedding code here under any circumstance.\n", "schedule": {"kind": "cron", "cron": "0 6 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/openworker-tasks/__task__task-ecad448aa3", "origin_surface": "cowork", "origin_session_id": "", "agent": "repo-ops", "id": "task-ecad448aa3", "task_session_id": "__task__task-ecad448aa3", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "mcp__qdrant__qdrant-qdrant-find", "mcp__qdrant__qdrant-qdrant-store", "read_file", "read_file_lines", "remember", "run_shell", "todo_write", "write_file"], "always_allowed_commands": [], "enabled": true, "created_at": 1787415295.9085045, "updated_at": 1788516516.236264, "next_run": 1788602400.0, "last_run": 1788516006.9442153, "last_status": "ok", "run_count": 13, "max_runs": null, "seen_runs_at": 1788445174.0836415}');
INSERT INTO scheduled_tasks VALUES('task-fe38324f51',1,1788606900.0,'{"title": "Application prep - field-by-field answer sheets", "instructions": "Prepare applications so that filing one takes me ten minutes instead of\nan evening. You do the research and the field-by-field answers. I do the typing.\n\n## WHY THIS JOB NO LONGER SUBMITTS ANYTHING\nIt used to try. Across 15 runs it sent exactly one application - Sprinter Health on\n2026-09-01, an Ashby form asking for name, email and a resume upload. Every application\nthat actually mattered came back `manual`, because the auto-fill threshold is 8 fields and\n2 dropdowns and real forms are nothing like that: Further was 15 required fields and 7\ncombobox dropdowns; MATS is five sections including four essays, two references and a work\nsample. The one form it could file was the one that barely needed automating.\n\nSo the submitting is gone, along with every tool that could type into a form or send one.\nWhat remained valuable is the part that always worked: reading a form live, working out\nexactly what it asks, and answering every field that can be answered from the record. A\ncomplete answer sheet is the deliverable. Producing one is a SUCCESSFUL run.\n\n## WHAT IS STAGED FOR YOU, by plain filename\n  targets.md    - the shortlist to work from.\n  facts.md      - the applicant''s verified facts. THE ONLY SOURCE for personal details.\n  resume.txt    - the resume as text.\n  drafts/       - cover letters and resume tweaks already written per target.\n  grants.md     - the funding digest.\n  opportunities.md - live deadlines. Read it; it is maintained elsewhere.\n  ledger.md     - every application ever attempted. READ IT FIRST.\n\n## METHOD\n1. Read ledger.md. Anything listed is DONE - never re-prepare it. A `skipped` row with\n   \"do not re-attempt\" is final; ERA:AI is skipped permanently because its form requires\n   certifying that no AI was used, which an AI-assisted application cannot honestly do.\n2. Pick AT MOST TWO targets. Order: a closing deadline first, then the best fit. Two\n   prepared properly beats five half-read.\n3. Open the real form. Follow the \"Apply\" link through to the ATS - the posting page and\n   the form are different pages and only the form tells you what is actually asked.\n   FIRST check the posting is still open: two of five targets had closed between being\n   shortlisted and being reached. A closed posting is a `closed` ledger row and no more work.\n4. Enumerate EVERY field: label, type, required or optional, and for a dropdown the actual\n   options on screen. This is the part that saves me the evening.\n5. Answer every field you can from facts.md and resume.txt, verbatim where they give a\n   verbatim answer.\n6. For anything you cannot answer, write **UNANSWERABLE** and say exactly what is missing.\n   NEVER invent a fact. Not a reference contact, not a date, not an affiliation, not a\n   degree. A previous run correctly refused to invent two reference contacts; do that\n   every time. An invented fact in an application is worse than an unfiled application.\n7. Flag any field that is genuinely my decision - office location, salary, a track choice,\n   an AI-use disclosure - as **MY CALL**, with the considerations, and do not answer it.\n\n## WRITE, per target, into apply-prep-<slug>.md\n  - The direct form URL, and the date you confirmed the posting open.\n  - How long the form is: sections, required fields, dropdowns, uploads, essays.\n  - The field-by-field answer sheet, in the order the form asks, ready to paste.\n  - UNANSWERABLE items, with what is needed to close each.\n  - MY CALL items, with the trade-off stated in one line.\n  - Which files in drafts/ apply, and whether they still fit what the form asks for.\n  - Any ethical blocker, stated plainly. An AI-use PROHIBITION is a hard stop. An AI-use\n    DISCLOSURE requirement is not - MATS explicitly permits disclosed AI use and says it\n    is not a basis for rejection, which is the opposite of ERA:AI. Check which one it is\n    and quote the page.\n  - The honest fit gap. If the posting wants 12 years and I have 2.5, say so.\n\nThen append one row per target to ledger.md. Status vocabulary now:\n  `prepared` - answer sheet written, ready for me to file\n  `blocked`  - cannot be prepared; say what blocks it (login, missing fact, assessment)\n  `closed`   - the posting closed before we reached it\n  `skipped`  - deliberately not pursued, with the reason\n(`sent` and `manual` remain on historical rows. Do not create new ones.)\n\n## YOU CANNOT SUBMIT, AND MUST NOT TRY\nThe tools that type into a form, upload to one, or submit one have been removed. You can\nopen pages, read them, click through navigation and take screenshots - that is all, and it\nis deliberate. Do not attempt to work around it, do not ask for it back, and never state\nor imply that an application was filed. The ledger''s `sent` column means a human sent it.\n\n## BUDGET AND OUTPUT\nAt most 40 tool calls. Two targets prepared completely is the goal; if one form is huge,\none is a fine run - say so. Write apply-prep-<slug>.md as your final action. A run that\nreads a form carefully and produces a complete answer sheet has done its whole job.\n\nCONTINUITY & FOCUS - two reads, before anything else:\n  1. read_file FOCUS.md in your workspace. Its first line names the week\n     (\"# FOCUS - week of YYYY-MM-DD\"); if that is more than 8 days old, say so in one line\n     and treat its ranking as weak evidence. FOCUS.md''s standing open question about this\n     pipeline is whether it converts or only accumulates drafts - your answer to that is\n     the count of prepared sheets I can actually act on, not the count of drafts written.\n  2. list_files your workspace and read ledger.md plus your last apply-prep-*.md. Carry\n     forward what is still open, and never re-prepare something already prepared.", "schedule": {"kind": "cron", "cron": "15 7 * * *", "fire_at": null, "timezone": "local"}, "workspace": "/home/iconbaypark2900/OpenWorker/__task__task-fe38324f51", "origin_surface": "cowork", "origin_session_id": "", "agent": "research", "id": "task-fe38324f51", "task_session_id": "__task__task-fe38324f51", "model": null, "notify_on_completion": true, "notify_target": null, "always_allowed_tools": ["brain_note", "brain_recall", "grep", "list_files", "read_file", "read_file_lines", "remember", "todo_write", "web_fetch", "web_search", "write_file", "browser_open_url", "browser_read_url", "browser_snapshot", "browser_get_text", "browser_click", "browser_wait", "browser_screenshot", "browser_close", "playwright-browser_navigate", "playwright-browser_snapshot", "playwright-browser_click", "playwright-browser_wait_for", "playwright-browser_take_screenshot", "playwright-browser_find", "playwright-browser_press_key", "playwright-browser_close"], "always_allowed_commands": [], "enabled": true, "created_at": 1788270695.288018, "updated_at": 1788520841.621156, "next_run": 1788606900.0, "last_run": 1788520506.98597, "last_status": "ok", "run_count": 12, "max_runs": null, "seen_runs_at": 1788375156.2701252}');
INSERT INTO task_runs VALUES('run-fdda11eeba','task-c685e22a0b',1786891901.302114,'{"task_id": "task-c685e22a0b", "run_id": "run-fdda11eeba", "started_at": 1786891901.302114, "finished_at": 1786892030.4916718, "status": "ok", "result_text": "Your morning briefing is ready \u2014 a 5-bullet digest of the last 24\u201336 hours:\n\n1. **Indonesia** \u2014 M7.7 quake off Flores killed 53+, injured 130+, with tsunamis and hampered relief\n2. **Red Sea** \u2014 Yemen suspended port operations after fresh Houthi ship attacks amid the US\u2013Iran conflict\n3. **Google** \u2014 launched Gemini 3.7 Flash, a cheaper, faster agentic/coding workhorse\n4. **Apple** \u2014 trained its own Chinese-market AI model with Alibaba, cleared by regulators\n5. **AI market** \u2014 OpenAI/Anthropic price cuts amid a ~$1.5T Big Tech AI capex buildout\n\n[Morning News Briefing 2026-08-16](artifact:morning-news-briefing-2026-08-16.md)", "artifacts": ["morning-news-briefing-2026-08-16.md"], "error": null, "trigger": "manual", "session_id": "__run__run-fdda11eeba"}');
