INSERT INTO task_runs VALUES('run-6caf84f439','task-f471043f3e',1787258643.24674797,'{"task_id": "task-f471043f3e", "run_id": "run-6caf84f439", "started_at": 1787258643.246748, "finished_at": 1787259335.6363358, "status": "ok", "result_text": "Watch complete \u2014 **breakage-2026-08-20.md** is written, ordered by breakage likelihood. Headlines: your most exposed area is the ROCm/unsloth/torch layer \u2014 ROCm 7.14.0 (July 16) migrated to TheRock/modular wheels and your 7.1.0 is 13 minors stale, and upgrades via `pip install -U` (especially unsloth) can silently swap torch to a CUDA build from PyPI \u2014 re-verify `torch.version.hip` after every upgrade. ollama v0.32.15 shipped yesterday with your installed 0.32.14 superseded (no breaks), llama.cpp is at b10519 (shipped today; spirv-headers is now a documented required Vulkan build dep) and the ROCm prebuilt asset is currently disabled, transformers is 10 minors ahead at v5.15.1 with the trust_remote_code import break class documented in-tree and fixed nowhere by the upgrade. For CMake 4.x/hipcc, LibreChat, OpenWorker, and the kernel I found nothing \u2014 noted as \"no changes found\" rather than padded. Every non-trivial claim cites a page I actually opened; snippet-only claims are flagged as such in the file.", "artifacts": ["breakage-2026-08-20.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-6caf84f439"}');
INSERT INTO task_runs VALUES('run-dad678e7a7','task-092a6d85f2',1787259363.25629806,'{"task_id": "task-092a6d85f2", "run_id": "run-dad678e7a7", "started_at": 1787259363.256298, "finished_at": 1787260793.0804157, "status": "ok", "result_text": "Done. The digest is saved as **`grants-2026-week-34.md`** (I initially wrote it as week-38 by miscounting the ISO week, then corrected the filename).\n\nWhat it contains, bottom line: **no deadline lands inside the 14-day urgent window this week** \u2014 the two real ones from last week (DARPA FALCON Aug 19, Lightcone/Corrigibility Aug 23) have since closed and are recorded as dropped. The nearest live hard deadlines are **DARPA \"Semantically-Aware ISR\" (Sep 23, flagged urgent-adjacent), an NSF SBIR Project Pitch by early September (full proposals due Nov 4), and NIH R43 on Jan 5, 2027** \u2014 all gated on incorporating a US company, which remains the single biggest eligibility blocker. Without a company, the honest set is the rolling independent-researcher grants that need no entity: **IBM Quantum Credits (best topical fit, apply first), the Coefficient Giving career-transition RFP (newly verified this run), fal, AIComputeFund, plus last week''s Leo Gao/BlueDot/AIAF/TAIF/Halcyon items** \u2014 carried forward and explicitly noted as un-re-verified. I also ruled out two look-alikes with straight-up \"probably not eligible / stretch\" verdicts: OpenAI''s Researcher Access program (requires academic affiliation) and the just-closed NSF ACCESS Maximize compute window (reopens ~Dec 15). Florida state funds came back empty \u2014 logged as a null result rather than padded with tax incentives.", "artifacts": ["grants-2026-week-34.md", "grants-2026-week-38.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-dad678e7a7"}');
INSERT INTO task_runs VALUES('run-7f954fbc8e','task-c6cf366b90',1787260833.27735352,'{"task_id": "task-c6cf366b90", "run_id": "run-7f954fbc8e", "started_at": 1787260833.2773535, "finished_at": 1787262254.6073642, "status": "ok", "result_text": "Done \u2014 the shortlist is written. Today was a thin day: I verified **4 plausible matches** and kept all four (below the ideal five, so I''m flagging that rather than padding).\n\n**Standard roles**\n1. **Dragos \u2014 Senior AI/ML Engineer** (US remote, $190k stated, rolling) \u2014 best standard-role fit: applied ML wired into production pipelines, Docker, PostgreSQL/SQL, and your Neo4j/Hetionet graph work clears their \"graph-based asset relationships\" nice-to-have. Main gap: their 5+ year bar vs. your ~2.5 years.\n2. **CrowdStrike \u2014 AI Platform Engineer** (US remote, no salary stated) \u2014 skills stack matches (Python/TS/Docker/GCP/REST), but the JD couldn''t be fully opened (Workday blocked) and it demands K8s/Terraform/OIDC plus ~3T events/day scale \u2014 applied last, ranked last.\n\n**Fellowships/residencies (paid)**\n3. **Perplexity \u2014 Research Residency** \u2014 **best match of the day**: $220k annualized, rolling (no fixed deadline), explicitly recruits non-PhD engineers with deep niche expertise; your quantum-classical QML project is a genuine differentiator.\n4. **Apple \u2014 2026 AIML Residency** \u2014 verified open, but it''s 1 year on-site and aimed at master''s/PhD grads; your resume lists no degree, so I ranked it speculative for possible degree-screening.\n\n**Excluded after checking:** IAPS AI Policy Fellowship (closed), Faculty Fellowship London (closed), OpenAI Residency 2026 (closed), HPE AI System Architect (Principal bar too high), various funding-only awards (belong in the grant digest, not here).\n\n**Files written:** `jobs-2026-08-20.md` (ranked shortlist with links, salaries, deadlines, fit/gaps per role) and `drafts/` containing, for the top 3: `cover-letter-perplexity.md`, `cover-letter-dragos.md`, `cover-letter-crowdstrike.md`, and matching `resume-tweaks-*.md` for each. Every claim in the drafts is sourced from resume bullets \u2014 nothing invented, and no applications submitted.", "artifacts": ["jobs-2026-08-20.md", "drafts/resume-tweaks-perplexity.md", "drafts/cover-letter-dragos.md", "drafts/resume-tweaks-dragos.md", "drafts/cover-letter-crowdstrike.md", "drafts/resume-tweaks-crowdstrike.md", "drafts/cover-letter-perplexity.md"], "error": null, "trigger": "schedule", "session_id": "__run__run-7f954fbc8e"}');
